// models/User.js
// User account model with secure password hashing.

const mongoose = require("mongoose");
const bcrypt = require("bcryptjs");

const userSchema = new mongoose.Schema(
  {
    email: {
      type: String,
      required: [true, "Email is required."],
      unique: true,
      lowercase: true,
      trim: true,
      match: [/^\S+@\S+\.\S+$/, "Please enter a valid email address."],
      index: true,
    },

    passwordHash: {
      type: String,
      required: true,
    },

    // ── Usage Tracking (for limits & merging guest usage) ──────────
    usage: {
      quickExplain: { type: Number, default: 0 },
      deepExplain: { type: Number, default: 0 }
    },

    // ── Password Reset (architecture-ready, flow can be wired later) ──────────
    resetPasswordToken: {
      type: String,
      default: null,
    },
    resetPasswordExpires: {
      type: Date,
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

// ── Instance Methods ──────────────────────────────────────────────────────────

/**
 * Compare a plain-text password against the stored hash.
 * @param {string} plainPassword
 * @returns {Promise<boolean>}
 */
userSchema.methods.comparePassword = function (plainPassword) {
  return bcrypt.compare(plainPassword, this.passwordHash);
};

module.exports = mongoose.model("User", userSchema);

